-- app.db schema version 4, for the v5 migration test.
CREATE TABLE "preferences" ("name" TEXT NOT NULL, "value" TEXT NOT NULL, PRIMARY KEY ("name"));
CREATE TABLE "clients" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "phone" TEXT NOT NULL UNIQUE, "chat_jid" TEXT NULL UNIQUE, "email" TEXT NOT NULL DEFAULT '', "address" TEXT NOT NULL DEFAULT '', "document" TEXT NOT NULL DEFAULT '', "birthday" TEXT NOT NULL DEFAULT '', "company" TEXT NOT NULL DEFAULT '', "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL);
CREATE TABLE "client_tags" ("client_id" INTEGER NOT NULL REFERENCES clients (id) ON DELETE CASCADE, "tag" TEXT NOT NULL, PRIMARY KEY ("client_id", "tag"));
CREATE TABLE "client_notes" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "client_id" INTEGER NOT NULL REFERENCES clients (id) ON DELETE CASCADE, "body" TEXT NOT NULL, "created_at" INTEGER NOT NULL);
CREATE TABLE "products" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "kind" TEXT NOT NULL, "name" TEXT NOT NULL, "sku" TEXT NULL UNIQUE, "barcode" TEXT NULL UNIQUE, "category" TEXT NOT NULL DEFAULT '', "brand" TEXT NOT NULL DEFAULT '', "supplier" TEXT NOT NULL DEFAULT '', "unit" TEXT NOT NULL DEFAULT 'UN', "description" TEXT NOT NULL DEFAULT '', "price" INTEGER NOT NULL, "promo_price" INTEGER NULL, "promo_until" TEXT NULL, "min_stock" INTEGER NOT NULL DEFAULT 0, "active" INTEGER NOT NULL DEFAULT 1 CHECK ("active" IN (0, 1)), "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL);
CREATE TABLE "product_attributes" ("product_id" INTEGER NOT NULL REFERENCES products (id) ON DELETE CASCADE, "position" INTEGER NOT NULL, "name" TEXT NOT NULL, "choices" TEXT NOT NULL, PRIMARY KEY ("product_id", "position"));
CREATE TABLE "product_variants" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "product_id" INTEGER NOT NULL REFERENCES products (id) ON DELETE CASCADE, "option1" TEXT NOT NULL DEFAULT '', "option2" TEXT NOT NULL DEFAULT '', "option3" TEXT NOT NULL DEFAULT '', "sku" TEXT NULL UNIQUE, "barcode" TEXT NULL UNIQUE, "price" INTEGER NULL, "cost" INTEGER NOT NULL DEFAULT 0, "stock" INTEGER NOT NULL DEFAULT 0, "active" INTEGER NOT NULL DEFAULT 1 CHECK ("active" IN (0, 1)));
CREATE TABLE "product_wholesale" ("product_id" INTEGER NOT NULL REFERENCES products (id) ON DELETE CASCADE, "min_qty" INTEGER NOT NULL, "price" INTEGER NOT NULL, PRIMARY KEY ("product_id", "min_qty"));
CREATE TABLE "sales" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "number" INTEGER NOT NULL UNIQUE, "client_id" INTEGER NULL REFERENCES clients (id) ON DELETE SET NULL, "client_removed" INTEGER NOT NULL DEFAULT 0 CHECK ("client_removed" IN (0, 1)), "sold_at" INTEGER NOT NULL, "discount" INTEGER NOT NULL DEFAULT 0, "freight" INTEGER NOT NULL DEFAULT 0, "total" INTEGER NOT NULL, "cost" INTEGER NOT NULL, "note" TEXT NOT NULL DEFAULT '', "canceled_at" INTEGER NULL, "cancel_reason" TEXT NOT NULL DEFAULT '', "created_at" INTEGER NOT NULL);
CREATE TABLE "stock_moves" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "variant_id" INTEGER NOT NULL REFERENCES product_variants (id) ON DELETE CASCADE, "kind" TEXT NOT NULL, "quantity" INTEGER NOT NULL, "unit_cost" INTEGER NULL, "reason" TEXT NOT NULL DEFAULT '', "note" TEXT NOT NULL DEFAULT '', "balance" INTEGER NOT NULL, "created_at" INTEGER NOT NULL, "sale_id" INTEGER NULL REFERENCES sales (id));
CREATE TABLE "product_photos" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "product_id" INTEGER NOT NULL REFERENCES products (id) ON DELETE CASCADE, "position" INTEGER NOT NULL, "bytes" BLOB NOT NULL, "created_at" INTEGER NOT NULL);
CREATE TABLE "sale_items" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "sale_id" INTEGER NOT NULL REFERENCES sales (id) ON DELETE CASCADE, "variant_id" INTEGER NOT NULL REFERENCES product_variants (id), "description" TEXT NOT NULL, "unit" TEXT NOT NULL, "is_service" INTEGER NOT NULL DEFAULT 0 CHECK ("is_service" IN (0, 1)), "quantity" INTEGER NOT NULL, "unit_price" INTEGER NOT NULL, "discount" INTEGER NOT NULL DEFAULT 0, "unit_cost" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "sale_payments" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "sale_id" INTEGER NOT NULL REFERENCES sales (id) ON DELETE CASCADE, "kind" TEXT NOT NULL, "method" TEXT NOT NULL, "amount" INTEGER NOT NULL, "paid_at" INTEGER NOT NULL, "voided" INTEGER NOT NULL DEFAULT 0 CHECK ("voided" IN (0, 1)));
CREATE TABLE "sale_installments" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "sale_id" INTEGER NOT NULL REFERENCES sales (id) ON DELETE CASCADE, "number" INTEGER NOT NULL, "due_date" TEXT NOT NULL, "amount" INTEGER NOT NULL);
